#!/usr/bin/env node
/*
 * build-content-bundle.js — OPT-IN content-script bundler.
 *
 * Why concatenation, not esbuild/module bundling:
 *   The content scripts are classic scripts that share ONE isolated-world global
 *   scope per page and coordinate through top-level function/var/window.* globals
 *   (no import/export). esbuild module-bundling gives each file its own scope and
 *   would break that shared-global coordination. Ordered byte concatenation
 *   preserves the exact semantics of sequential manifest injection — and is
 *   provably safe here because there are zero top-level const/let/class
 *   collisions across any co-injected page set (guarded by
 *   tests/content-load-order.test.js).
 *
 * What it produces:
 *   dist/content-bundles/<provider>.bundle.js — one file per provider page,
 *   equal to (shared block ∪ provider block) concatenated in manifest order.
 *   dist/ is gitignored, so this never ships or drifts in git.
 *
 * Status: NOT wired into the manifest. The project deliberately injects raw
 *   files to avoid a build step / staleness (see README + dist/ gitignore note).
 *   Adopting the bundle is an owner decision: it trades one-file parse for a
 *   rebuild-before-reload workflow. See
 *   docs/stabilization/global-code-review-2026-06-18.md §3 Phase 1.
 *
 * Usage: node scripts/build-content-bundle.js   (or: npm run build:content-bundle)
 */

const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const OUT_DIR = path.join(ROOT, 'dist', 'content-bundles');

const manifest = JSON.parse(fs.readFileSync(path.join(ROOT, 'manifest.json'), 'utf8'));
const blocks = manifest.content_scripts || [];
// Do not couple the build to manifest array position. A document_start MAIN-world
// bridge can legitimately precede the shared isolated-world runtime block.
const base = blocks.find((block) => (
  (block.js || []).includes('content-scripts/content-bootstrap.js')
  && (block.js || []).includes('content-scripts/content-utils.js')
));
const providerBlocks = blocks.filter((block) => block !== base && (block.js || []).some((file) => (
  /^content-scripts\/content-[a-z0-9-]+\.js$/i.test(file)
  && !file.endsWith('/content-bridge.js')
  && !file.endsWith('/content-bootstrap.js')
)));

const providerSlug = (block, idx) => {
  const host = (block.matches && block.matches[0]) || `block${idx}`;
  const m = host.match(/\/\/([^/*]+)/);
  return (m ? m[1] : `block${idx}`).replace(/[^a-z0-9]+/gi, '-');
};

const concat = (files) => files.map((rel) => {
  const abs = path.join(ROOT, rel);
  const src = fs.readFileSync(abs, 'utf8');
  return `\n/* ==== ${rel} ==== */\n${src}\n`;
}).join('');

const main = () => {
  if (!base) throw new Error('Cannot find the shared isolated-world content-script block');
  fs.mkdirSync(OUT_DIR, { recursive: true });
  const summary = [];
  for (const block of providerBlocks) {
    const index = blocks.indexOf(block);
    const files = [...base.js, ...(block.js || [])];
    const missing = files.filter((rel) => !fs.existsSync(path.join(ROOT, rel)));
    if (missing.length) {
      throw new Error(`Cannot bundle ${providerSlug(block, index)}: missing ${missing.join(', ')}`);
    }
    const header = `// AUTO-GENERATED by scripts/build-content-bundle.js — do not edit.\n`
      + `// Concatenation of ${files.length} content scripts in manifest order.\n`
      + `// Source of truth is the raw files; rebuild after any edit.\n`;
    const out = path.join(OUT_DIR, `${providerSlug(block, index)}.bundle.js`);
    fs.writeFileSync(out, header + concat(files));
    summary.push(`${path.relative(ROOT, out)}  (${files.length} files)`);
  }
  // eslint-disable-next-line no-console
  console.log(`Built ${summary.length} content bundles:\n  ${summary.join('\n  ')}`);
};

main();
